    "id": "ev-conservator-assess",
    "quote": "A conservator assesses the object's condition."
  },
  {
    "id": "ev-registrar-checks",
    "quote": "The registrar checks availability, insurance and transport arrangements."
  },
  {
    "id": "ev-committee-decision",
    "quote": "The lending committee makes the final loan decision."
  },
  {
    "id": "ev-ai-limits",
    "quote": "The assistant may prepare documents but cannot approve a loan, sign an agreement, publish an object's storage location or instruct a courier."
  },
  {
    "id": "ev-conservation-pending",
    "quote": "If conservation evidence is missing, the case stays pending until the conservator responds."
  },
  {
    "id": "ev-exhibition-conflict",
    "quote": "If the dates conflict with an existing exhibition, the registrar proposes alternatives."
  },
  {
    "id": "ev-handover-scheduling",
    "quote": "After approval, the registrar schedules the handover and records return-condition checks."
  },
  {
    "id": "ev-cancellation-reason",
    "quote": "A cancellation closes the request with a recorded reason."
  },
  {
    "id": "ev-storage-restriction",
    "quote": "Access to precise storage locations is restricted to authorised museum staff."
  },
  {
    "id": "ev-catalogue-api",
    "quote": "We have not selected a catalogue API"
  },
  {
    "id": "ev-retention-periods",
    "quote": "We have not defined retention periods"
  },
  {
